<script setup>
import{computed}from'vue';const props=defineProps({wheel:Object,actions:Array,selection:Object});const emit=defineEmits(['select']);
const center=computed(()=>Math.max(30,props.wheel.center/props.wheel.size*360)),split=computed(()=>center.value+(180-center.value)*.5);
const title=ring=>ring==='inner'?'第一圈':ring==='second'?'第二圈':'外圈';
function xy(r,a){const t=(a-90)*Math.PI/180;return [250+Math.cos(t)*r,250+Math.sin(t)*r]}
function path(inner,outer,a,b){const p=xy(outer,a),q=xy(outer,b),r=xy(inner,b),s=xy(inner,a);return `M${p} A${outer},${outer} 0 0 1 ${q} L${r} A${inner},${inner} 0 0 0 ${s} Z`}
function name(id){const a=props.actions.find(x=>x.id===id);return a?`${a.icon||''} ${a.name}`.trim():'＋ 配置'}
const sectors=computed(()=>{const list=[];for(const ring of props.wheel.secondEnabled?['inner','second']:['inner']){const n=ring==='inner'?props.wheel.count:props.wheel.secondCount,slots=ring==='inner'?props.wheel.slots:props.wheel.secondSlots;const a=ring==='inner'?center.value+3:split.value+2,b=ring==='inner'&&props.wheel.secondEnabled?split.value-2:177;for(let i=0;i<n;i++)list.push({ring,index:i,label:name(slots[i]),path:path(a,b,(i-.5)*360/n+1,(i+.5)*360/n-1),point:xy((a+b)/2,i*360/n)})}return list});
const outside=computed(()=>{if(!props.wheel.outsideEnabled)return [];if(props.wheel.outsideMode==='single')return [{ring:'outside',index:0,label:name(props.wheel.outsideActionId)}];return Array.from({length:props.wheel.outsideCount},(_,i)=>({ring:'outside',index:i,label:name(props.wheel.outsideSlots[i]),path:path(186,400,(i-.5)*360/props.wheel.outsideCount,(i+.5)*360/props.wheel.outsideCount),point:xy(195,i*360/props.wheel.outsideCount)}))});
const selected=s=>props.selection?.ring===s.ring&&props.selection?.index===s.index;
</script>
<template><div class="wheel-editor wheel-editor-v3"><svg viewBox="45 45 410 410" class="editable-wheel"  aria-label="第一圈、第二圈及无边界外圈"><defs><filter id="wheel-soft-shadow" x="-30%" y="-30%" width="160%" height="160%"><feDropShadow dx="0" dy="4" stdDeviation="6" flood-color="#253746" flood-opacity=".09"/></filter></defs><g v-if="wheel.outsideEnabled&&wheel.outsideMode==='single'" class="outside-surface" :class="{chosen:selection?.ring==='outside'}" role="button" tabindex="0" :aria-label="'外圈：'+outside[0]?.label+'，无外边界'" @click="emit('select',{ring:'outside',index:0})" @keydown.enter.prevent="emit('select',{ring:'outside',index:0})"><rect x="46" y="46" width="408" height="408" rx="22"/><text x="250" y="60" text-anchor="middle">∞ 外圈 · {{outside[0]?.label}}</text><text x="250" y="442" text-anchor="middle">超出轮盘即进入 · 无外边界</text></g><g v-for="s in wheel.outsideMode==='direction'?outside:[]" :key="'outside'+s.index" class="outside-sector" :class="{chosen:selected(s)}" role="button" tabindex="0" :aria-label="'外圈第'+(s.index+1)+'方向：'+s.label" @click="emit('select',{ring:'outside',index:s.index})" @keydown.enter.prevent="emit('select',{ring:'outside',index:s.index})"><path :d="s.path"/><text :x="s.point[0]" :y="s.point[1]" text-anchor="middle" dominant-baseline="middle">{{s.label.slice(0,7)}}</text></g><circle cx="250" cy="250" r="182" class="wheel-disc" filter="url(#wheel-soft-shadow)"/><g v-for="s in sectors" :key="s.ring+s.index" class="editable-sector" :class="{chosen:selected(s)}" role="button" tabindex="0" :aria-label="`${title(s.ring)}第${s.index+1}项：${s.label}`" @click="emit('select',{ring:s.ring,index:s.index})" @keydown.enter.prevent="emit('select',{ring:s.ring,index:s.index})" @keydown.space.prevent="emit('select',{ring:s.ring,index:s.index})"><path :d="s.path"/><text :x="s.point[0]" :y="s.point[1]" text-anchor="middle" dominant-baseline="middle">{{s.label.length>8?s.label.slice(0,7)+'…':s.label}}</text></g><circle cx="250" cy="250" :r="center-3" class="wheel-center"/><text x="250" y="248" text-anchor="middle" class="wheel-center-label">鼠快快</text><text x="250" y="266" text-anchor="middle" class="wheel-center-hint">点击配置</text></svg><p class="hint">第一圈与第二圈是可见扇区；外圈从轮盘边缘向外无限延伸。</p></div></template>
